package com.bank.audit;

import java.util.concurrent.*;
import java.util.logging.*;

public class BufferChoiceDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        final String accountId = "SAV2001"; // immutable String, read by all threads safely
        int threads = 6, perThread = 500, expected = threads * perThread;

        SharedBufferAudit safe = new SharedBufferAudit();   // StringBuffer: correct shared case
        SharedBuilderAudit unsafe = new SharedBuilderAudit(); // StringBuilder shared: WRONG

        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch latch = new CountDownLatch(threads);
        for (int t = 0; t < threads; t++) {
            final int id = t;
            pool.submit(() -> {
                for (int i = 0; i < perThread; i++) {
                    String entry = accountId + "-w" + id + "-" + i;
                    safe.record(entry);     // synchronized → safe
                    unsafe.record(entry);   // not synchronized → racy
                }
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();

        log.info(() -> "Expected lines = " + expected);
        log.info(() -> "Shared StringBuffer lines  = " + safe.lineCount() + " (CORRECT)");
        log.warning(() -> "Shared StringBuilder lines = " + unsafe.lineCount()
                           + " (CORRUPTED under concurrency)");
        log.info("Senior recommendation: prefer per-thread StringBuilder merged at end.");
    }
}

// ─── Would be SharedBufferAudit.java in a real project ───
class SharedBufferAudit {
    private final StringBuffer buffer = new StringBuffer(16384); // synchronized methods
    void record(String entry) { buffer.append(entry).append('\n'); } // atomic per call
    long lineCount() { return buffer.toString().lines().count(); }
}

// ─── Would be SharedBuilderAudit.java in a real project ───
class SharedBuilderAudit {
    private final StringBuilder buffer = new StringBuilder(16384); // NOT synchronized
    void record(String entry) { buffer.append(entry).append('\n'); } // racy across threads
    long lineCount() { return buffer.toString().lines().count(); }
}

// ─── Would be ThreadLocalAudit.java in a real project (faster alternative) ───
class ThreadLocalAudit {
    private final ThreadLocal<StringBuilder> local = ThreadLocal.withInitial(StringBuilder::new);
    void record(String entry) { local.get().append(entry).append('\n'); } // no lock, no sharing
    String drain() { return local.get().toString(); } // merge per-thread results at the end
}
